const packages=[
{name:'Budget',price:1500000,description:'Эхний алхмаа бүтээлчээр эхлүүл.',summary:'3 постер · 1 Reel<br>Chatbot · Профайл, ковер<br>Boost хийх заавар',items:[['Постер',3,300000],['Reel',1,500000],['Chatbot',1,500000],['Профайл, ковер',1,100000],['Boost хийх заавар',1,100000]]},
{name:'Standard',price:3000000,description:'Дүр төрхөө нэгтгэж, контентоо нэм.',summary:'8 постер · 2 Reel<br>Chatbot · Brandbook<br>Профайл, ковер · Boost заавар',items:[['Постер',8,800000],['Reel',2,1000000],['Chatbot',1,500000],['Brandbook',1,500000],['Профайл, ковер',1,100000],['Boost хийх заавар',1,100000]]},
{name:'Pro',price:4600000,description:'Сошиалаас вэб хүртэл нэг өнгөөр.',summary:'10 постер · 3 Reel<br>Chatbot · Brandbook · Вэб<br>Профайл, ковер · Boost заавар',items:[['Постер',10,1000000],['Reel',3,1500000],['Chatbot',1,500000],['Brandbook',1,500000],['Профайл, ковер',1,100000],['Boost хийх заавар',1,100000],['Вэб / танилцуулга',1,900000]]},
{name:'Premium',price:13100000,description:'Дизайнаас аппликейшн хүртэл.',summary:'10 постер · 4 Reel<br>Pro-ийн үйлчилгээ + аппликейшн<br>Брэнд ба дижитал шийдэл',items:[['Постер',10,1000000],['Reel',4,2000000],['Chatbot',1,500000],['Brandbook',1,500000],['Профайл, ковер',1,100000],['Boost хийх заавар',1,100000],['Вэб / танилцуулга',1,900000],['Аппликейшн',1,8000000]]}
];
const singles=[['Постер',100000],['Reel',500000],['Chatbot',500000],['Brandbook',500000],['Профайл, ковер',100000],['Boost хийх заавар',100000],['Вэб / танилцуулга',900000],['Аппликейшн',8000000]];
const money=n=>n.toLocaleString('en-US');
document.querySelector('#packages').innerHTML=packages.map((p,i)=>`<article class="package ${i===2?'pro':''}"><h3>${p.name}</h3><p class="description">${p.description}</p><div class="price">${money(p.price)} <small>₮</small></div><p class="package-summary">${p.summary}</p><a href="#contact" data-service="${p.name} багц" class="button">Багц сонгох ↗</a><button class="package-detail-button" data-package="${i}">Багцын дэлгэрэнгүй</button></article>`).join('');
document.querySelector('#single').innerHTML=singles.map(([n,p])=>`<div class="single-row"><span>${n}</span><strong>${money(p)} ₮</strong></div>`).join('');
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b));});document.querySelector('#packages').hidden=b.dataset.tab!=='packages';document.querySelector('#single').hidden=b.dataset.tab!=='single';}));
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('[name=service]').value=a.dataset.service;document.querySelector('.brief-result').hidden=true;}));
document.querySelectorAll('[data-package]').forEach(b=>b.addEventListener('click',()=>{const p=packages[+b.dataset.package];document.querySelector('#package-detail').innerHTML=`<div class="eyebrow">CHAMELEON / БАГЦ</div><h3>${p.name} багц</h3>${p.items.map(([n,q,v])=>`<div class="detail-row"><span>${n} × ${q}</span><strong>${money(v)} ₮</strong></div>`).join('')}<div class="detail-total">Нийт: ${money(p.price)} ₮</div><p class="detail-note">Мөр бүрийн үнэ нь тухайн тоо хэмжээний нийт дүн. Ажлын хүрээ, материал, хугацааг урьдчилан тохирно.</p><a class="button dark" id="choose-detail" href="#contact">Энэ багцыг сонгох ↗</a>`;document.querySelector('#package-dialog').showModal();document.querySelector('#choose-detail').addEventListener('click',()=>{document.querySelector('[name=service]').value=p.name+' багц';document.querySelector('#package-dialog').close();document.querySelector('.brief-result').hidden=true;});}));
document.querySelectorAll('.work-item').forEach(b=>b.addEventListener('click',()=>{const d=document.querySelector('#work-dialog');d.querySelector('h3').textContent=b.dataset.title;d.querySelector('img').src='assets/'+b.dataset.image;d.querySelector('img').alt=b.dataset.title;d.showModal();}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=document.querySelector('#nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Цэс хаах':'Цэс нээх');});document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#nav').classList.remove('open');menu.setAttribute('aria-expanded','false');}));
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const p=packages.find(p=>p.name+' багц'===f.get('service'));const text=`Сайн байна уу, Chameleon!\n\nБайгууллага / нэр: ${f.get('name').trim()}\nХэрэгтэй үйлчилгээ: ${f.get('service')}${p?'\nБагцын үнэ: '+money(p.price)+' ₮':''}\nХүссэн хугацаа: ${f.get('deadline').trim()||'Хамтран тохирно'}\n\nТөслийн тухай:\n${f.get('description').trim()}\n\nАжлын хүрээ, хугацаа, төлбөртэй үнийн санал авах хүсэлтэй байна.`;document.querySelector('#brief-output').value=text;document.querySelector('.brief-result').hidden=false;document.querySelector('#brief-status').textContent='Хүсэлт бэлэн. Хуулж аваад Chameleon-д зурвасаар илгээгээрэй.';document.querySelector('.brief-result').scrollIntoView({block:'nearest',behavior:'smooth'});});
document.querySelector('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#brief-output').value);document.querySelector('#brief-status').textContent='Зурвас хуулагдлаа.';}catch{const t=document.querySelector('#brief-output');t.focus();t.select();document.querySelector('#brief-status').textContent='Текстийг сонголоо. Ctrl+C эсвэл Copy ашиглан хуулна уу.';}});
document.querySelector('#download-brief').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([document.querySelector('#brief-output').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Chameleon-хүсэлт.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
